<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
import ProductPackageManager from './ProductPackageManager.vue'
import CommerceIntegrationManager from './CommerceIntegrationManager.vue'
const $q = useQuasar(), busy = ref(false)
const form = reactive({ available: false, price: '', original: '', monthly: '', monthlyEnabled: true, monthlyTitle: '', monthlyDescription: '', desktopDownloadUrl:'', renderDownloadUrl:'', monthlyWhatsapp: '', media: {} })
const mediaFields = [{ key: 'teamAccess', label: 'Print de múltiplos atendentes e responsáveis' }, { key: 'heroVideo', label: 'Vídeo principal (MP4 ou YouTube)' }, { key: 'heroPoster', label: 'Capa do vídeo' }, { key: 'cloudDashboard', label: 'Print do painel da API oficial' }, { key: 'scheduler', label: 'Print de programação de envios' }, { key: 'mobilePush', label: 'Print do app e da notificação no celular' }, { key: 'whiteLabel', label: 'Print da personalização de marca' }, { key: 'botFlow', label: 'Print do editor de fluxos' }, { key: 'botChats', label: 'Print das conversas e atendimento' }]
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_admin_token') || ''}` } })
function apply(v) { Object.assign(form, v, { price: v.priceCents / 100, original: v.originalPriceCents / 100, monthly: v.monthlyPriceCents == null ? '' : v.monthlyPriceCents / 100, media: { ...v.media } }) }
onMounted(async () => { try { apply((await api.get('/admin/products/aitonotify/offer', headers())).data.data) } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.message || 'Não foi possível carregar a oferta.' }) } })
async function save() { busy.value = true; try { const cents = value => Math.round(Number(String(value).replace(',', '.')) * 100); const data = { ...form, priceCents: cents(form.price), originalPriceCents: cents(form.original), monthlyPriceCents: form.monthly === '' ? null : cents(form.monthly) }; apply((await api.put('/admin/products/aitonotify/offer', data, headers())).data.data); $q.notify({ type: 'positive', message: 'Preços, planos e apresentação atualizados.' }) } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.message || 'Confira os dados da oferta.' }) } finally { busy.value = false } }
</script>
<template><q-card flat bordered class="offer-admin q-mb-xl"><q-card-section><span class="offer-eyebrow">KIT AITONOTIFY + WHATSAPP BOTBUILDER · OFERTA COMERCIAL</span><h2>Dois planos. Uma página atualizada.</h2><p>Os valores e mídias abaixo aparecem em /whatsapp-solucoes. O preço confirmado no checkout fica registrado no pedido.</p></q-card-section><q-form @submit="save"><q-card-section class="offer-fields"><q-toggle color="teal-4" v-model="form.available" label="Liberar compra do código-fonte"/><q-toggle color="teal-4" v-model="form.monthlyEnabled" label="Exibir plano mensal"/><q-input dark stack-label v-model="form.price" outlined label="Código-fonte · preço (R$)" inputmode="decimal"/><q-input dark stack-label v-model="form.original" outlined label="Código-fonte · preço original (R$)" inputmode="decimal"/><q-input dark stack-label v-model="form.monthly" outlined label="Mensalidade (R$)" inputmode="decimal" hint="Vazio apresenta o plano sob consulta."/><q-input dark stack-label v-model="form.monthlyWhatsapp" outlined label="WhatsApp comercial com DDI e DDD"/><q-input dark stack-label v-model="form.monthlyTitle" outlined label="Nome do plano mensal" maxlength="100"/><q-input dark stack-label v-model="form.monthlyDescription" outlined type="textarea" autogrow label="O que está incluído no acompanhamento mensal" maxlength="500"/></q-card-section><q-expansion-item dark icon="mdi-image-multiple-outline" label="Vídeo, imagens e prints da landing page" class="q-mx-md"><q-card-section class="offer-fields"><q-input dark stack-label v-for="field in mediaFields" :key="field.key" v-model.trim="form.media[field.key]" outlined :label="field.label" hint="URL HTTPS da mídia. Vazio mantém o espaço demonstrativo."/></q-card-section></q-expansion-item><q-card-actions align="right"><q-btn unelevated color="teal-7" no-caps type="submit" label="Salvar planos e página" :loading="busy"/></q-card-actions></q-form><CommerceIntegrationManager/><ProductPackageManager/></q-card></template>
<style scoped>.offer-admin{background:#092324;color:#effffb;border-color:#2b5855;border-radius:18px}.offer-admin h2{font-size:24px;line-height:1.3;margin:8px 0}.offer-admin p{color:#b9d6d0;font-size:13px}.offer-eyebrow{font-size:10px;letter-spacing:.14em;color:#8fffee}.offer-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.offer-admin :deep(.q-field__native),.offer-admin :deep(.q-field__label),.offer-admin :deep(.q-field__messages){color:#d1e9e2}.offer-admin :deep(.q-field__control:before){border-color:#52766e}@media(max-width:700px){.offer-fields{grid-template-columns:1fr}}</style>
